class Product {
    String name;
    double price;
    int stockQuantity;

    // Parameterized constructor enforcing all required fields
    Product(String pName, double pPrice, int pStock) {
        name = pName;
        price = pPrice;
        stockQuantity = pStock;
    }

    void displayCard() {
        System.out.println("📦 " + name + " | Price: $" + price + " | Stock: " + stockQuantity);
    }
}

public class Main {
    public static void main(String[] args) {
        // Instantiating 2 independent products with their own data
        Product p1 = new Product("Mechanical Keyboard", 89.99, 15);
        Product p2 = new Product("Gaming Mouse", 49.50, 40);

        p1.displayCard();
        p2.displayCard();
    }
}

class FlightTicket {
    String passengerName;
    String flightCode;
    String seatNumber;
    double baggageWeightKg;

    FlightTicket(String name, String flight, String seat, double weight) {
        passengerName = name;
        flightCode = flight;
        seatNumber = seat;
        baggageWeightKg = weight;
    }

    void printBoardingPass() {
        System.out.println("✈️ PASS: " + passengerName + " | Flight: " + flightCode + " | Seat: " + seatNumber + " | Luggage: " + baggageWeightKg + "kg");
    }
}

public class Main {
    public static void main(String[] args) {
        FlightTicket t1 = new FlightTicket("Vikram Rao", "AI-202", "14A", 18.5);
        t1.printBoardingPass();
    }
}

