practiceProblems.solutionCode:
class Book {
    String title;
    String author;

    Book(String bTitle, String bAuthor) {
        title = bTitle;
        author = bAuthor;
    }

    void printInfo() {
        System.out.println(title + " by " + author);
    }
}

public class Main {
    public static void main(String[] args) {
        Book b = new Book("Atomic Habits", "James Clear");
        b.printInfo();
    }
}

class Ticket {
    String movieName;
    String seatNumber;
    double price;

    Ticket(String m, String s, double p) {
        movieName = m;
        seatNumber = s;
        price = p;
    }
}

public class Main {
    public static void main(String[] args) {
        Ticket t1 = new Ticket("Inception", "A-12", 12.50);
        Ticket t2 = new Ticket("Interstellar", "B-05", 15.00);
        System.out.println("Ticket 1: " + t1.movieName + " [" + t1.seatNumber + "] - $" + t1.price);
        System.out.println("Ticket 2: " + t2.movieName + " [" + t2.seatNumber + "] - $" + t2.price);
    }
}

class Rectangle {
    double width;
    double height;

    Rectangle(double w, double h) {
        width = w;
        height = h;
    }

    double getArea() {
        return width * height;
    }
}

public class Main {
    public static void main(String[] args) {
        Rectangle rect = new Rectangle(4.5, 2.0);
        System.out.println("Area: " + rect.getArea());
    }
}

class Account {
    String owner;
    double balance;

    Account(String o, double b) {
        owner = o;
        if (b < 0) {
            balance = 0.0;
        } else {
            balance = b;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Account acc = new Account("Charlie", -50.0);
        System.out.println("Account: " + acc.owner + " | Balance: $" + acc.balance);
    }
}

class Point {
    int x, y;

    Point(int px, int py) {
        x = px;
        y = py;
    }

    Point(Point other) {
        x = other.x;
        y = other.y;
    }
}

public class Main {
    public static void main(String[] args) {
        Point p1 = new Point(10, 20);
        Point p2 = new Point(p1);
        System.out.println("Clone Point -> X: " + p2.x + ", Y: " + p2.y);
    }
}
